import{_ as t,o as a,c as o,aF as r}from"./chunks/framework.CNkxH4QO.js";const p=JSON.parse('{"title":"krawler-rte","description":"A Krawler based job to download generation data from the French electrical network operated by RTE.","frontmatter":{"title":"krawler-rte","description":"A Krawler based job to download generation data from the French electrical network operated by RTE."},"headers":[],"relativePath":"packages/krawler-rte/index.md","filePath":"packages/krawler-rte/index.md"}'),d={name:"packages/krawler-rte/index.md"};function n(i,e,l,c,s,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="krawler-rte" tabindex="-1">krawler-rte <a class="header-anchor" href="#krawler-rte" aria-label="Permalink to &quot;krawler-rte&quot;">​</a></h1><p><em>A Krawler based job to download generation data from the French electrical network operated by RTE.</em></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The <strong>krawler-rte</strong> job scrapes generation data from the <a href="https://data.rte-france.com/" target="_blank" rel="noreferrer">RTE API</a>. The downloaded data are stored within a <a href="https://www.mongodb.com/" target="_blank" rel="noreferrer">MongoDB</a> database and more precisely in 2 collections:</p><ul><li>the <code>rte-generation</code> collection stores the production units generation data</li><li>the <code>rte-units</code> collection stores the production units positions</li></ul><p>All records are stored in <a href="https://fr.wikipedia.org/wiki/GeoJSON" target="_blank" rel="noreferrer">GeoJson</a> format.</p><p>The project consists in 2 jobs:</p><ul><li>the <code>units</code> job scrapes the available production units according a specific cron expression. By default, every day at midnight.</li><li>the <code>generation</code> job scrapes the generation data according a specific cron expression. By default every hour.</li></ul><p>As the RTE API does not provide the location of the production units, the default <code>units</code> job simply reads data from input files providing plant location and associated production units (taken from <a href="https://github.com/ewoken/nuclear-monitor" target="_blank" rel="noreferrer">https://github.com/ewoken/nuclear-monitor</a>), assuming all production units of the plant have the same location. You can update the file whenever production units are updated.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><h3 id="production-units" tabindex="-1">Production units <a class="header-anchor" href="#production-units" aria-label="Permalink to &quot;Production units&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>DB_URL</code></td><td>The database URL. The default value is <code>mongodb://127.0.0.1:27017/rte</code></td></tr><tr><td><code>DEBUG</code></td><td>Enables debug output. Set it to <code>krawler*</code> to enable full output. By default it is undefined.</td></tr></tbody></table><h3 id="generation-data" tabindex="-1">Generation data <a class="header-anchor" href="#generation-data" aria-label="Permalink to &quot;Generation data&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>DB_URL</code></td><td>The database URL. The default value is <code>mongodb://127.0.0.1:27017/rte</code></td></tr><tr><td><code>TTL</code></td><td>The observations data time to live. It must be expressed in seconds and the default value is <code>604 800</code> (7 days)</td></tr><tr><td><code>CLIENT_ID</code></td><td>Client ID of your application in the RTE API, required to generate the authentication token.</td></tr><tr><td><code>CLIENT_SECRET</code></td><td>Client secret of your application in the RTE API, required to generate the authentication token.</td></tr><tr><td><code>PRODUCTION_TYPE_FILTER</code></td><td>Comma-separated list of production type to be read (please refer to RTE API documentation for details, defaults to <code>NUCLEAR</code>).</td></tr><tr><td><code>HISTORY</code></td><td>The duration of the generation data history the job has to download. It must be expressed in seconds and the default value is <code>86 400 000</code> (1 day)</td></tr><tr><td><code>DEBUG</code></td><td>Enables debug output. Set it to <code>krawler*</code> to enable full output. By default it is undefined.</td></tr></tbody></table><h2 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h2><p>We personally use <a href="https://kalisio.github.io/kargo/" target="_blank" rel="noreferrer">Kargo</a> to deploy the service.</p>',16)])])}const b=t(d,[["render",n]]);export{p as __pageData,b as default};
